select year(c.signup_date) as signup_year, c.segment, round((100 * sum(case when we.page = '/checkout' then 1 else 0 end)) / count(*), 1) as pct_checkout from web_events we join sessions s on s.id = we.session_id left join customers c on s.customer_id = c.id where we.event_type in ('purchase', 'click', 'page_view') group by year(c.signup_date), c.segment having pct_checkout >= 46 order by pct_checkout desc
